[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Fresh Pantry — Discover Everyday Deliciousness</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
    <style>
        :root {
            --brand-primary: oklch(47% 0.12 152);
            --brand-primary-dark: oklch(40% 0.10 152);
            --brand-accent: oklch(76% 0.16 65);
            --brand-accent-dark: oklch(68% 0.16 65);
            --bg-cream: oklch(97% 0.02 90);
            --bg-white: oklch(100% 0 0);
            --text-primary: oklch(25% 0.02 152);
            --text-secondary: oklch(50% 0.02 152);
            --text-light: oklch(70% 0.02 152);
            --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
            --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
            --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 20px;
            --radius-xl: 28px;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background-color: var(--bg-cream);
            color: var(--text-primary);
            line-height: 1.6;
        }

        h1, h2, h3, h4, h5, h6 {
            font-family: 'Nunito', sans-serif;
            font-weight: 700;
            line-height: 1.2;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px;
        }

        /* Header */
        .header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            background: var(--bg-white);
            box-shadow: var(--shadow-sm);
            z-index: 100;
            padding: 0 24px;
        }

        .header-inner {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 72px;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 10px;
            text-decoration: none;
            color: var(--brand-primary);
        }

        .logo-icon {
            width: 40px;
            height: 40px;
            background: var(--brand-primary);
            border-radius: var(--radius-sm);
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 20px;
        }

        .logo-text {
            font-family: 'Nunito', sans-serif;
            font-size: 24px;
            font-weight: 800;
        }

        .nav {
            display: flex;
            gap: 32px;
        }

        .nav a {
            text-decoration: none;
            color: var(--text-primary);
            font-weight: 500;
            font-size: 15px;
            transition: color 0.2s;
        }

        .nav a:hover {
            color: var(--brand-primary);
        }

        .nav-cta {
            background: var(--brand-primary);
            color: white !important;
            padding: 10px 20px;
            border-radius: var(--radius-md);
            transition: background 0.2s;
        }

        .nav-cta:hover {
            background: var(--brand-primary-dark);
        }

        .mobile-menu-btn {
            display: none;
            background: none;
            border: none;
            font-size: 24px;
            cursor: pointer;
            color: var(--text-primary);
        }

        /* Hero */
        .hero {
            padding: 140px 0 80px;
            background: linear-gradient(135deg, var(--bg-cream) 0%, var(--bg-white) 100%);
            overflow: hidden;
        }

        .hero-inner {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
        }

        .hero-content h1 {
            font-size: 56px;
            font-weight: 800;
            color: var(--brand-primary);
            margin-bottom: 20px;
            letter-spacing: -0.02em;
        }

        .hero-content p {
            font-size: 18px;
            color: var(--text-secondary);
            margin-bottom: 32px;
            max-width: 480px;
        }

        .hero-buttons {
            display: flex;
            gap: 16px;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 14px 28px;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 16px;
            text-decoration: none;
            cursor: pointer;
            border: none;
            transition: all 0.2s;
        }

        .btn-primary {
            background: var(--brand-primary);
            color: white;
        }

        .btn-primary:hover {
            background: var(--brand-primary-dark);
            transform: translateY(-2px);
            box-shadow: var(--shadow-md);
        }

        .btn-secondary {
            background: var(--brand-accent);
            color: var(--text-primary);
        }

        .btn-secondary:hover {
            background: var(--brand-accent-dark);
            transform: translateY(-2px);
            box-shadow: var(--shadow-md);
        }

        .hero-visual {
            position: relative;
        }

        .hero-image {
            width: 100%;
            height: 420px;
            border-radius: var(--radius-xl);
            background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
            box-shadow: var(--shadow-lg);
        }

        .hero-image-placeholder {
            font-size: 120px;
            opacity: 0.6;
        }

        .hero-badge {
            position: absolute;
            bottom: -20px;
            left: -20px;
            background: white;
            padding: 16px 24px;
            border-radius: var(--radius-md);
            box-shadow: var(--shadow-md);
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .hero-badge-icon {
            width: 44px;
            height: 44px;
            background: var(--brand-accent);
            border-radius: var(--radius-sm);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
        }

        .hero-badge-text {
            font-weight: 600;
            font-size: 14px;
        }

        .hero-badge-text span {
            display: block;
            color: var(--text-secondary);
            font-weight: 400;
        }

        /* Brand Highlights */
        .brand-highlights {
            background: var(--brand-primary);
            padding: 60px 0;
        }

        .highlights-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 40px;
        }

        .highlight-item {
            text-align: center;
            color: white;
        }

        .highlight-number {
            font-family: 'Nunito', sans-serif;
            font-size: 48px;
            font-weight: 800;
            line-height: 1;
            margin-bottom: 8px;
        }

        .highlight-label {
            font-size: 15px;
            opacity: 0.9;
        }

        /* Featured Products */
        .featured-products {
            padding: 100px 0;
        }

        .section-header {
            text-align: center;
            margin-bottom: 48px;
        }

        .section-header h2 {
            font-size: 40px;
            color: var(--brand-primary);
            margin-bottom: 12px;
        }

        .section-header p {
            font-size: 18px;
            color: var(--text-secondary);
        }

        .carousel-wrapper {
            position: relative;
        }

        .carousel {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            scroll-behavior: smooth;
            scrollbar-width: none;
            -ms-overflow-style: none;
            padding: 10px 0;
        }

        .carousel::-webkit-scrollbar {
            display: none;
        }

        .product-card {
            flex: 0 0 240px;
            background: white;
            border-radius: var(--radius-lg);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
            transition: transform 0.3s, box-shadow 0.3s;
        }

        .product-card:hover {
            transform: translateY(-6px);
            box-shadow: var(--shadow-lg);
        }

        .product-image {
            width: 100%;
            height: 180px;
            background: linear-gradient(135deg, #f5f5f5 0%, #e8e8e8 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 64px;
        }

        .product-info {
            padding: 20px;
        }

        .product-name {
            font-weight: 700;
            font-size: 16px;
            margin-bottom: 6px;
            color: var(--text-primary);
        }

        .product-desc {
            font-size: 13px;
            color: var(--text-secondary);
            margin-bottom: 12px;
            line-height: 1.4;
        }

        .product-price {
            font-family: 'Nunito', sans-serif;
            font-size: 22px;
            font-weight: 700;
            color: var(--brand-primary);
        }

        .carousel-btn {
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background: white;
            border: none;
            box-shadow: var(--shadow-md);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            color: var(--brand-primary);
            transition: all 0.2s;
            z-index: 10;
        }

        .carousel-btn:hover {
            background: var(--brand-primary);
            color: white;
            transform: translateY(-50%) scale(1.1);
        }

        .carousel-btn.prev {
            left: -24px;
        }

        .carousel-btn.next {
            right: -24px;
        }

        /* Seasonal Picks */
        .seasonal-picks {
            padding: 80px 0;
            background: linear-gradient(180deg, var(--bg-white) 0%, var(--bg-cream) 100%);
        }

        .seasonal-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
        }

        .seasonal-card {
            background: white;
            border-radius: var(--radius-lg);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
            transition: transform 0.3s, box-shadow 0.3s;
        }

        .seasonal-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-md);
        }

        .seasonal-image {
            width: 100%;
            height: 140px;
            background: linear-gradient(135deg, #fff3e0 0%, #ffe0b2 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 56px;
        }

        .seasonal-info {
            padding: 20px;
        }

        .seasonal-name {
            font-weight: 700;
            font-size: 15px;
            margin-bottom: 6px;
        }

        .seasonal-desc {
            font-size: 13px;
            color: var(--text-secondary);
            margin-bottom: 10px;
            line-height: 1.4;
        }

        .seasonal-price {
            font-family: 'Nunito', sans-serif;
            font-size: 20px;
            font-weight: 700;
            color: var(--brand-accent-dark);
        }

        /* Categories */
        .categories {
            padding: 100px 0;
        }

        .categories-grid {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 20px;
        }

        .category-card {
            position: relative;
            height: 200px;
            border-radius: var(--radius-lg);
            overflow: hidden;
            cursor: pointer;
            background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 64px;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .category-card:nth-child(2) {
            background: linear-gradient(135deg, #fff8e1 0%, #ffecb3 100%);
        }

        .category-card:nth-child(3) {
            background: linear-gradient(135deg, #e3f2fd 0%, #bbdefb 100%);
        }

        .category-card:nth-child(4) {
            background: linear-gradient(135deg, #fce4ec 0%, #f8bbd9 100%);
        }

        .category-card:nth-child(5) {
            background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%);
        }

        .category-card:hover {
            transform: scale(1.05);
            box-shadow: var(--shadow-lg);
        }

        .category-overlay {
            position: absolute;
            inset: 0;
            background: oklch(0% 0 0 / 0.6);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .category-card:hover .category-overlay {
            opacity: 1;
        }

        .category-name {
            color: white;
            font-family: 'Nunito', sans-serif;
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 8px;
        }

        .category-link {
            color: white;
            font-size: 14px;
            opacity: 0.9;
        }

        /* Store Locator */
        .store-locator {
            padding: 100px 0;
            background: var(--bg-white);
        }

        .locator-box {
            background: white;
            border-radius: var(--radius-xl);
            padding: 60px;
            box-shadow: var(--shadow-lg);
            text-align: center;
            max-width: 700px;
            margin: 0 auto;
        }

        .locator-box h2 {
            font-size: 36px;
            color: var(--brand-primary);
            margin-bottom: 12px;
        }

        .locator-box > p {
            color: var(--text-secondary);
            margin-bottom: 32px;
        }

        .search-form {
            display: flex;
            gap: 12px;
            max-width: 420px;
            margin: 0 auto 32px;
        }

        .search-input {
            flex: 1;
            padding: 14px 20px;
            border: 2px solid #e0e0e0;
            border-radius: var(--radius-md);
            font-size: 16px;
            font-family: inherit;
            transition: border-color 0.2s;
        }

        .search-input:focus {
            outline: none;
            border-color: var(--brand-primary);
        }

        .search-btn {
            background: var(--brand-primary);
            color: white;
            border: none;
            padding: 14px 28px;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 16px;
            cursor: pointer;
            transition: background 0.2s;
        }

        .search-btn:hover {
            background: var(--brand-primary-dark);
        }

        .store-results {
            display: none;
            text-align: left;
            margin-top: 32px;
        }

        .store-results.active {
            display: block;
        }

        .store-result {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px;
            border: 1px solid #e8e8e8;
            border-radius: var(--radius-md);
            margin-bottom: 12px;
            transition: border-color 0.2s, box-shadow 0.2s;
        }

        .store-result:hover {
            border-color: var(--brand-primary);
            box-shadow: var(--shadow-sm);
        }

        .store-name {
            font-weight: 700;
            font-size: 16px;
            margin-bottom: 4px;
            color: var(--brand-primary);
        }

        .store-address {
            font-size: 14px;
            color: var(--text-secondary);
        }

        .store-hours {
            font-size: 13px;
            color: var(--text-light);
            margin-top: 4px;
        }

        .store-distance {
            background: var(--bg-cream);
            padding: 8px 16px;
            border-radius: var(--radius-sm);
            font-weight: 600;
            font-size: 14px;
            color: var(--brand-primary);
        }

        /* Newsletter */
        .newsletter {
            padding: 80px 0;
            background: linear-gradient(135deg, var(--brand-accent) 0%, #e8976a 100%);
        }

        .newsletter-inner {
            text-align: center;
            color: white;
        }

        .newsletter h2 {
            font-size: 36px;
            margin-bottom: 12px;
        }

        .newsletter p {
            font-size: 18px;
            opacity: 0.95;
            margin-bottom: 32px;
            max-width: 500px;
            margin-left: auto;
            margin-right: auto;
        }

        .newsletter-form {
            display: flex;
            gap: 12px;
            max-width: 420px;
            margin: 0 auto;
        }

        .newsletter-input {
            flex: 1;
            padding: 14px 20px;
            border: none;
            border-radius: var(--radius-md);
            font-size: 16px;
            font-family: inherit;
        }

        .newsletter-input:focus {
            outline: none;
            box-shadow: 0 0 0 3px oklch(0% 0 0 / 0.2);
        }

        .newsletter-btn {
            background: var(--brand-primary);
            color: white;
            border: none;
            padding: 14px 28px;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 16px;
            cursor: pointer;
            transition: background 0.2s;
        }

        .newsletter-btn:hover {
            background: var(--brand-primary-dark);
        }

        .newsletter-confirmation {
            display: none;
            padding: 20px;
            background: oklch(0% 0 0 / 0.15);
            border-radius: var(--radius-md);
            margin-top: 20px;
            font-weight: 600;
        }

        .newsletter-confirmation.active {
            display: block;
        }

        /* Footer */
        .footer {
            background: var(--text-primary);
            color: white;
            padding: 80px 0 40px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr repeat(3, 1fr);
            gap: 60px;
            margin-bottom: 60px;
        }

        .footer-brand .logo-text {
            font-size: 28px;
            color: white;
            margin-bottom: 16px;
        }

        .footer-brand p {
            color: oklch(70% 0.02 152);
            font-size: 14px;
            line-height: 1.7;
            max-width: 280px;
        }

        .footer-col h4 {
            font-size: 14px;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 20px;
            color: oklch(70% 0.02 152);
        }

        .footer-col a {
            display: block;
            color: white;
            text-decoration: none;
            font-size: 14px;
            margin-bottom: 12px;
            transition: color 0.2s;
        }

        .footer-col a:hover {
            color: var(--brand-accent);
        }

        .footer-bottom {
            border-top: 1px solid oklch(30% 0.02 152);
            padding-top: 30px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 14px;
            color: oklch(60% 0.02 152);
        }

        .footer-social {
            display: flex;
            gap: 20px;
        }

        .footer-social a {
            color: oklch(60% 0.02 152);
            text-decoration: none;
            font-size: 16px;
            transition: color 0.2s;
        }

        .footer-social a:hover {
            color: white;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .hero-inner {
                grid-template-columns: 1fr;
                text-align: center;
            }

            .hero-content h1 {
                font-size: 44px;
            }

            .hero-content p {
                margin-left: auto;
                margin-right: auto;
            }

            .hero-buttons {
                justify-content: center;
            }

            .hero-visual {
                display: none;
            }

            .highlights-grid {
                grid-template-columns: repeat(2, 1fr);
                gap: 30px;
            }

            .categories-grid {
                grid-template-columns: repeat(3, 1fr);
            }

            .footer-grid {
                grid-template-columns: 1fr 1fr;
            }
        }

        @media (max-width: 768px) {
            .nav {
                display: none;
            }

            .mobile-menu-btn {
                display: block;
            }

            .hero {
                padding: 100px 0 60px;
            }

            .hero-content h1 {
                font-size: 36px;
            }

            .section-header h2 {
                font-size: 32px;
            }

            .carousel-btn {
                display: none;
            }

            .seasonal-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .categories-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .category-card {
                height: 160px;
            }

            .search-form,
            .newsletter-form {
                flex-direction: column;
            }

            .store-result {
                flex-direction: column;
                text-align: center;
                gap: 12px;
            }

            .footer-grid {
                grid-template-columns: 1fr;
                gap: 40px;
            }

            .footer-bottom {
                flex-direction: column;
                gap: 20px;
                text-align: center;
            }
        }
    </style>
</head>
<body>
    <!-- Header -->
    <header class="header">
        <div class="header-inner">
            <a href="#" class="logo">
                <div class="logo-icon">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
                        <path d="M12 2L2 7l10 5 10-5-10-5z"/>
                        <path d="M2 17l10 5 10-5"/>
                        <path d="M2 12l10 5 10-5"/>
                    </svg>
                </div>
                <span class="logo-text">Fresh Pantry</span>
            </a>
            <nav class="nav">
                <a href="#">Products</a>
                <a href="#">Our Stores</a>
                <a href="#">Recipes</a>
                <a href="#">About Us</a>
                <a href="#" class="nav-cta">Find a Store</a>
            </nav>
            <button class="mobile-menu-btn" aria-label="Menu">☰</button>
        </div>
    </header>

    <!-- Hero -->
    <section class="hero">
        <div class="container">
            <div class="hero-inner">
                <div class="hero-content">
                    <h1>Discover Everyday Deliciousness</h1>
                    <p>Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.</p>
                    <div class="hero-buttons">
                        <a href="#store-locator" class="btn btn-primary">Find a Store Near You</a>
                        <a href="#featured-products" class="btn btn-secondary">Explore This Week's Picks</a>
                    </div>
                </div>
                <div class="hero-visual">
                    <div class="hero-image">
                        <div class="hero-image-placeholder">🥬</div>
                    </div>
                    <div class="hero-badge">
                        <div class="hero-badge-icon">🏪</div>
                        <div class="hero-badge-text">
                            500+ Stores
                            <span>Across the nation</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Brand Highlights -->
    <section class="brand-highlights">
        <div class="container">
            <div class="highlights-grid">
                <div class="highlight-item">
                    <div class="highlight-number">500+</div>
                    <div class="highlight-label">Stores Nationwide</div>
                </div>
                <div class="highlight-item">
                    <div class="highlight-number">4,000+</div>
                    <div class="highlight-label">Unique Products</div>
                </div>
