    <script>
        // Product Carousel
        function scrollCarousel(direction) {
            const carousel = document.getElementById('productCarousel');
            const cardWidth = 264; // card width + gap
            carousel.scrollBy({
                left: direction * cardWidth * 2,
                behavior: 'smooth'
            });
        }

        // Store Search
        document.getElementById('storeSearchForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const zip = document.getElementById('zipInput').value;
            if (zip.length === 5) {
                document.getElementById('storeResults').classList.add('active');
            }
        });

        // Newsletter Signup
        document.getElementById('newsletterForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const email = document.getElementById('emailInput').value;
            if (email) {
                document.getElementById('newsletterConfirmation').classList.add('active');
                document.getElementById('emailInput').value = '';
            }
        });

        // Smooth scroll for anchor links
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            });
        });
    </script>
